def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Edge case: single cell
    if N == 1:
        return grid[1][1]

    # Initialize DP arrays
    NEG_INF = -10**18
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    # Total steps from 2 to 2N
    for step in range(3, 2 * N + 1):
        new_dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = step - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = step - i2
                if j2 < 1 or j2 > N:
                    continue
                best_prev = NEG_INF
                # four possible previous moves
                for pi1, pi2 in ((i1 - 1, i2 - 1), (i1 - 1, i2), (i1, i2 - 1), (i1, i2)):
                    if pi1 < 1 or pi2 < 1:
                        continue
                    best_prev = max(best_prev, dp[pi1][pi2])
                if best_prev == NEG_INF:
                    continue
                add = 0
                if i1 == i2 and j1 == j2:
                    add = grid[i1][j1]
                else:
                    add = grid[i1][j1] + grid[i2][j2]
                new_dp[i1][i2] = best_prev + add
        dp = new_dp

    return dp[N][N]

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    avg, eval_score = grades
    scholarship = 0
    if avg > 80 and papers >= 1:
        scholarship += 8000
    if avg > 85 and eval_score > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == 'Y':
