def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # The encoded and original strings must be of the same length to form a valid mapping
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"  # Contradiction: same encoded letter maps to different originals
        else:
            mapping[e] = o

    # The mapping must cover all 26 letters and be bijective
    if len(mapping) < 26 or len(set(mapping.values())) < 26:
        return "Failed"

    # Decode the message using the mapping
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"  # Message contains a letter not in the mapping
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine truth of a guilt statement
    def evaluate(statement: str, speaker: str) -> bool | None:
        s = statement.strip()
        # Skip if statement is about day of week
        upper_s = s.upper()
        for day in days_of_week:
            if day.upper() in upper_s:
                return None  # ignore day-of-week statements

        # Recognize guilt statements
        if s == "I am guilty.":
            return speaker == scenario
        if s == "I am not guilty.":
            return speaker != scenario
        # Patterns like "NAME is guilty." or "NAME is not guilty."
        if s.endswith(" is guilty.") and len(s.split()) >= 3:
            name = s.split()[0]
            return name == scenario
        if s.endswith(" is not guilty.") and len(s.split()) >= 4:
            name = s.split()[0]
            return name != scenario
        # If statement not recognized, ignore it
        return None

    for speaker, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate(stmt, speaker)
            if truth is None:
                continue  # skip non-guilt or day-of-week statements
            if speaker in liar_count:
                if truth:
                    return False  # liar said a true statement
            else:
                if not truth:
                    return False  # truth-teller said a false statement
    return True

